import pygame

def event_action(event_type, key=None):
    if event_type == pygame.QUIT:
        return "quit"
    if event_type == pygame.KEYDOWN:
        if key == pygame.K_ESCAPE:
            return "quit"
        if key == pygame.K_SPACE:
            return "toggle"
    return None
